/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Candidate
 *   Functions: release, candidate, view, bestOf, discNumbers, trackNumbers, numberOnes, live, message, cr, read
 *   Constants: bestOfContext, liveContext
 * Tests
 *   - a completed run names its possible releases and why no edition is confirmed: no tracks, members without a duration or an unclear pairing, then a release left unused
 *   - a tie, an offered release, none applied and an applied release keep their own sentence under the count, and an applied release names itself
 *   - an active run names its phase and counts with the draft usable meanwhile, its time and that it keeps running in the log
 *   - a run that failed says the lookup has not finished, with when and which retry, why retries ran out or it stopped, and the free retry as the next step
 *   - without a run the lookup has not run: the name box is next where lookup is configured, else the shared not-configured sentence
 *   - while Luna AI runs its headline replaces the lookup's, alone keeping whether the name box is next, beside an active lookup both are named
 * @end-catalog */

import type { ReviewLookupView } from './importLookupApi';
import { pairedLookupResponse, pairingApplication, pairingEditions, pairingLookupResponse } from './catalogReviewLookupFixtures.testSupport';
import { elapsedText, reviewStatusLine, type StatusLine } from './reviewStatusLine';

/**
 * The review page's one status line without rendering: its headline, sentence, icon and log lines, and whether the name box is the
 * next step, for each state of the lookup and while Luna AI runs. The views keep the shapes of real runs (a live Album without
 * numbers, an Album without durations, an Album without members); every name and identifier is synthetic.
 */
type Candidate = ReviewLookupView['candidates'][number];
const release = (n: number) => `0000000b-0000-4000-8000-${String(n).padStart(12, '0')}`;
/** A review candidate: unverified with members fitting in more than one way unless `extra` says otherwise. */
const candidate = (n: number, title: string, extra: Partial<Candidate> & { pairing?: 'unique' | 'ambiguous' | 'none' | null; local?: number; unknown?: number } = {}): Candidate => {
  const { pairing = 'ambiguous', local = 2, unknown = 0, ...rest } = extra;
  return { key: `musicbrainz:${release(n)}`, releaseId: release(n), source: 'musicbrainz', notChecked: false, status: 'unverified', title, artist: 'Synthetic Singer', label: 'Synthetic Label',
    catalogNumber: `SYN-${n}`, barcode: String(4006381330000 + n), country: 'JP', date: { year: 2016, month: 1, day: 1 }, formats: ['CD'], trackCount: 44,
    comparison: { trackCount: { local, candidate: 44 }, discCount: { local: null, candidate: 3 }, differences: [], unknownLocalDurations: unknown, unknownCandidateDurations: 0,
      subset: { leftOutTracks: 0, pairing, pairs: [], missingTrackCount: 44 - local, unpairableSlotIds: [] } }, groupKey: null, artistMismatch: false, artwork: false, byTrackTitle: false, ...rest };
};
const view = (candidates: Candidate[], extra: Partial<ReviewLookupView> = {}): ReviewLookupView => ({ ...pairingLookupResponse().lookup!, input: { trigger: 'catalog', submitted: null },
  candidates, disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: false }, ...extra });
/** An Album without durations: 14 releases its tracks fit (4 editions of its best-of with exactly its title) and one that does not. */
const bestOf = (pairing: 'unique' | 'ambiguous' = 'ambiguous') => view([...['Synthetic Seven Sins', 'Synthetic Snow Flower', 'Synthetic Message', 'Synthetic Best', 'Synthetic Will', 'Synthetic Love',
  'Synthetic Stars', 'Synthetic Seventeen', 'Synthetic Wish', 'Synthetic Glamorous'].map((title, index) => candidate(index + 1, title, { unknown: 3, local: 3 })),
...[11, 12, 13, 14].map(n => candidate(n, 'Synthetic Best BIBLE', { unknown: 3, local: 3, pairing })),
candidate(15, 'Synthetic Single', { status: 'notMatching', pairing: 'none', local: 3 })], { disclosure: { unknownLocalDurations: 3, unknownLocalDiscNumbers: 3, partialComparison: false } });
const discNumbers = (count: number) => ({ numbers: {}, count, disc: true }), trackNumbers = (count: number) => ({ numbers: {}, count, disc: false });
const bestOfContext = { status: 'lookup.no_match', luna: false, members: 3, searched: 'Synthetic Best BIBLE／Synthetic Singer', artists: ['Synthetic Singer'], now: 0, numbers: discNumbers(3) };
/** An Album without members: releases found by its title alone, six of them with exactly its title. */
const numberOnes = () => view(Array.from({ length: 12 }, (_, index) => candidate(index + 1, index % 2 ? `Other ${index}` : 'Synthetic Number Ones', { local: 0, pairing: 'unique' })));
const live = (extra: Partial<ReviewLookupView> = {}) => ({ ...pairingLookupResponse().lookup!, ...extra });
const liveContext = { status: 'lookup.no_match', luna: false, members: 2, searched: 'Synthetic Live Album 2', artists: ['Synthetic Live Artist -Romanized-'], now: 0, numbers: discNumbers(2) };
const message = (key: string, values?: Record<string, string | number>) => ({ key, values });
const cr = (key: string, values?: Record<string, string | number>) => message(`catalog_review.${key}`, values);
/** The parts of a line a test reads: icon, headline, sentence and whether the name box is next. */
const read = (line: StatusLine) => ({ tone: line.tone, head: line.head, line: line.line, box: line.box });

test('a completed run names its possible releases and why no edition is confirmed: no tracks, members without a duration or an unclear pairing, then a release left unused', () => {
  // The owner's Album: 4 possible releases (14 fitting records), 3 tracks without a duration, the titles proposing every number.
  expect(read(reviewStatusLine(bestOf(), bestOfContext))).toEqual({ tone: 'check', head: cr('lookup_head_complete', { count: 4 }), line: cr('lookup_line_numbers', { unknown: 3 }), box: false });
  // Track Numbers alone, or none, are entered by hand: the name box is next.
  expect(read(reviewStatusLine(bestOf(), { ...bestOfContext, numbers: trackNumbers(3) }))).toEqual({ tone: 'check', head: cr('lookup_head_complete', { count: 4 }),
    line: cr('lookup_line_name', { unknown: 3 }), box: true });
  expect(reviewStatusLine(bestOf(), { ...bestOfContext, numbers: null }).box).toBe(true);
  // Without a possible match the other releases the tracks fit are counted.
  expect(reviewStatusLine(bestOf(), { ...bestOfContext, searched: 'Synthetic Unrelated', numbers: null }).head).toEqual(cr('lookup_head_complete', { count: 14 }));
  // A pairing that is not single while every duration is known: no member without a duration.
  expect(read(reviewStatusLine(live(), liveContext))).toEqual({ tone: 'check', head: cr('lookup_head_complete', { count: 1 }), line: cr('lookup_line_numbers', { unknown: 0 }), box: false });
  expect(reviewStatusLine(live(), { ...liveContext, numbers: discNumbers(0) }).line).toEqual(cr('lookup_line_name', { unknown: 0 }));
  expect(reviewStatusLine(live(), { ...liveContext, status: 'lookup.itunes_unavailable' }).line).toEqual(cr('lookup_line_numbers', { unknown: 0 }));
  // A release the tracks pair with in one way, left unused for unknown durations: using it is next, never the numbers.
  expect(read(reviewStatusLine(bestOf('unique'), bestOfContext))).toEqual({ tone: 'check', head: cr('lookup_head_complete', { count: 4 }), line: cr('lookup_line_use', { unknown: 3 }), box: false });
  const reshaped = view(live().candidates.map(entry => entry.status === 'unverified'
    ? { ...entry, comparison: { ...entry.comparison!, subset: { ...entry.comparison!.subset!, pairing: 'unique' as const } } } : entry));
  expect(reviewStatusLine(reshaped, liveContext).line).toEqual(cr('lookup_line_use', { unknown: 0 }));
  // An Album without tracks names its releases with the searched name; the name box stays next.
  expect(read(reviewStatusLine(numberOnes(), { ...liveContext, members: 0, searched: 'Synthetic Number Ones', artists: [], numbers: null }))).toEqual({ tone: 'check',
    head: cr('lookup_head_complete', { count: 6 }), line: cr('lookup_line_no_tracks'), box: true });
  // A real no match, and no release or nothing to search: nothing found, the name box next.
  for (const status of ['lookup.no_match', 'lookup.no_release', 'lookup.no_query', 'lookup.itunes_unavailable'])
    expect(read(reviewStatusLine(view(live().candidates.filter(entry => entry.status !== 'unverified')), { ...liveContext, status })), status)
      .toEqual({ tone: 'search', head: cr('lookup_head_empty'), line: cr('lookup_line_empty'), box: true });
});

test('a tie, an offered release, none applied and an applied release keep their own sentence under the count, and an applied release names itself', () => {
  const groups = view(live().candidates, { groups: [{}, {}] as never });
  expect(read(reviewStatusLine(groups, { ...liveContext, status: 'lookup.tie' }))).toEqual({ tone: 'check', head: cr('lookup_head_complete', { count: 2 }), line: cr('lookup_tie'), box: false });
  expect(reviewStatusLine(groups, { ...liveContext, status: 'lookup.single_choice' }).line).toEqual(cr('lookup_single_choice'));
  expect(reviewStatusLine(groups, { ...liveContext, status: 'lookup.applied_none' }).line).toEqual(cr('lookup_applied_none'));
  // An applied release whose pairing a saved number has since made single: using it again brings in its tracklist.
  const again = pairedLookupResponse(pairingApplication(pairingEditions[0], false)).lookup!;
  expect(read(reviewStatusLine(again, { ...liveContext, status: 'lookup.applied' }))).toEqual({ tone: 'check', head: message('lookup.applied', { title: 'Synthetic Live Album 2' }),
    line: cr('lookup_line_again'), box: false });
  // Applied with members still without a duration: they stay unverified; else no sentence.
  const applied = pairedLookupResponse(pairingApplication(pairingEditions[0], true)).lookup!;
  expect(reviewStatusLine({ ...applied, disclosure: { unknownLocalDurations: 3, unknownLocalDiscNumbers: 0, partialComparison: false } }, { ...liveContext, status: 'lookup.applied' }).line)
    .toEqual(cr('lookup_line_unverified', { count: 3 }));
  expect(reviewStatusLine({ ...applied, disclosure: null }, { ...liveContext, status: 'lookup.applied' }).line).toBeNull();
  expect(read(reviewStatusLine(applied, { ...liveContext, status: 'lookup.applied_itunes_unchecked' }))).toMatchObject({ tone: 'alert', head: { key: 'lookup.applied_itunes_unchecked' }, line: null });
});

test('an active run names its phase and counts with the draft usable meanwhile, its time and that it keeps running in the log', () => {
  const startedAt = '2026-10-25T00:00:00.000Z', start = Date.parse(startedAt), progress = (extra: object) => ({ phase: 'details' as const, done: 3, total: 8, startedAt, updatedAt: startedAt, ...extra });
  const line = (state: ReviewLookupView['state'], extra: object | null, now: number) => reviewStatusLine(view([], { state, ...(extra ? { progress: progress(extra) } : {}) }),
    { ...liveContext, status: 'lookup.active', now });
  expect(line('queued', { phase: 'search', done: 0, total: 2 }, start + 20_000)).toEqual({ tone: 'clock', head: cr('lookup_queued_status'), line: cr('lookup_line_running'),
    notes: [cr('lookup_waited', { elapsed: '0:20' }), cr('lookup_keeps_running')], box: false });
  expect(line('running', {}, start + 14_000)).toMatchObject({ head: cr('lookup_running_count_status', { phase: 'details', done: 3, total: 8 }),
    notes: [cr('lookup_elapsed', { elapsed: '0:14' }), cr('lookup_keeps_running')] });
  expect(line('running', { phase: 'itunes', done: 0, total: 0 }, start + 5_000).head).toEqual(cr('lookup_running_status', { phase: 'itunes', done: 0, total: 0 }));
  // A client clock behind the server's counts to the run's last step instead.
  expect(line('running', { updatedAt: '2026-10-25T00:00:09.000Z' }, start - 60_000).notes[0]).toEqual(cr('lookup_elapsed', { elapsed: '0:09' }));
  expect(line('running', { updatedAt: 'unreadable' }, start - 5_000).notes[0].values).toEqual({ elapsed: '0:00' });
  // Without progress the shared status heads the line, and the log only says it keeps running.
  expect(line('running', null, start)).toMatchObject({ head: { key: 'lookup.active' }, notes: [cr('lookup_keeps_running')] });
  expect([elapsedText(0), elapsedText(999), elapsedText(61_000), elapsedText(3_725_000), elapsedText(-1_000), elapsedText(Number.NaN)]).toEqual(['0:00', '0:00', '1:01', '62:05', '0:00', '0:00']);
});

test('a run that failed says the lookup has not finished, with when and which retry, why retries ran out or it stopped, and the free retry as the next step', () => {
  const at = '2026-10-22T01:26:10.000Z', timeline = (retry: object | null) => ({ steps: [], startedAt: at, updatedAt: at, completedAt: null, retry }) as NonNullable<ReviewLookupView['timeline']>;
  const retrying = (issue: ReviewLookupView['issue'], retry: object | null, time?: (value: string) => string) =>
    reviewStatusLine(view([], { state: 'retrying', issue, timeline: timeline(retry) }), { ...liveContext, status: 'lookup.retrying', ...(time ? { time } : {}) });
  const musicBrainz = { at, source: 'musicbrainz', attempt: 2, limit: 3 }, failed = cr('lookup_head_failed');
  expect(read(retrying('sourceBusy', musicBrainz, value => `time of ${value}`))).toEqual({ tone: 'alert', head: failed,
    line: cr('lookup_retry_busy', { source: 'MusicBrainz', time: `time of ${at}`, attempt: 2, limit: 3 }), box: false });
  expect(retrying('sourceUnavailable', { ...musicBrainz, source: 'itunes', attempt: 1 }).line).toEqual(cr('lookup_retry_unavailable', { source: 'iTunes', time: at, attempt: 1, limit: 3 }));
  expect(retrying(null, musicBrainz).line!.key).toBe('catalog_review.lookup_retry_busy');
  // A server that sends no retry time keeps the shared retrying sentence.
  expect(retrying('sourceBusy', null).line).toEqual(message('lookup.retrying'));
  const ended = (state: ReviewLookupView['state'], issue: ReviewLookupView['issue'], status: string) => read(reviewStatusLine(view([], { state, issue }), { ...liveContext, status }));
  expect(ended('unavailable', 'sourceBusy', 'lookup.unavailable')).toEqual({ tone: 'alert', head: failed, line: cr('lookup_exhausted_busy'), box: false });
  expect(ended('complete', 'sourceUnavailable', 'lookup.unavailable').line).toEqual(cr('lookup_exhausted_unavailable'));
  expect(ended('stopped', 'grantExpired', 'lookup.stopped').line).toEqual(cr('lookup_stopped_time'));
  expect(ended('stopped', 'permissionLost', 'lookup.stopped').line).toEqual(cr('lookup_stopped_permission'));
  for (const [state, issue, status] of [['stopped', null, 'lookup.stopped'], ['complete', 'sourceBusy', 'lookup.incomplete'], ['unavailable', null, 'lookup.unavailable']] as const)
    expect(ended(state, issue, status), status).toEqual({ tone: 'alert', head: failed, line: cr('lookup_line_failed'), box: false });
  // A superseded run offers no retry: the name box is next.
  expect(ended('superseded', 'projectClosed', 'lookup.superseded')).toEqual({ tone: 'alert', head: failed, line: cr('lookup_superseded'), box: true });
});

test('without a run the lookup has not run: the name box is next where lookup is configured, else the shared not-configured sentence', () => {
  expect(read(reviewStatusLine(null, { ...liveContext, status: 'lookup.not_started' }))).toEqual({ tone: 'search', head: cr('lookup_head_none'), line: cr('lookup_line_empty'), box: true });
  expect(read(reviewStatusLine(null, { ...liveContext, status: 'lookup.not_configured' }))).toEqual({ tone: 'search', head: cr('lookup_head_none'), line: message('lookup.not_configured'), box: false });
  expect(reviewStatusLine(view([], { state: 'unavailable', issue: 'notConfigured' }), { ...liveContext, status: 'lookup.not_configured' }).head).toEqual(cr('lookup_head_none'));
});

test('while Luna AI runs its headline replaces the lookup\'s, alone keeping whether the name box is next, beside an active lookup both are named', () => {
  expect(read(reviewStatusLine(bestOf(), { ...bestOfContext, luna: true }))).toEqual({ tone: 'clock', head: cr('status_luna'), line: cr('status_luna_line'), box: false });
  expect(reviewStatusLine(bestOf(), { ...bestOfContext, numbers: null, luna: true }).box).toBe(true);
  const startedAt = '2026-10-25T00:00:00.000Z';
  const running = view([], { state: 'running', progress: { phase: 'details', done: 3, total: 8, startedAt, updatedAt: startedAt } });
  expect(reviewStatusLine(running, { ...liveContext, status: 'lookup.active', luna: true, now: Date.parse(startedAt) + 3_000 })).toEqual({ tone: 'clock', head: cr('status_both_running'),
    line: cr('status_both_line'), notes: [cr('lookup_elapsed', { elapsed: '0:03' }), cr('lookup_keeps_running')], box: false });
});
